mapper.select:
SELECT   WHERE s.deleted=FALSE AND p.id IS NOT NULL AND p.master_status='ENABLED'
AND s.status=#{query.status}
AND s.spu_id=#{query.spuId}
AND (s.sku_code ILIKE CONCAT('%',#{query.keyword},'%') OR s.barcode ILIKE CONCAT('%',#{query.keyword},'%') OR s.spec_name ILIKE CONCAT('%',#{query.keyword},'%') OR p.name ILIKE CONCAT('%',#{query.keyword},'%') OR p.alias ILIKE CONCAT('%',#{query.keyword},'%') OR p.mnemonic_code ILIKE CONCAT('%',#{query.keyword},'%'))
ORDER BY s.sku_code,s.id LIMIT #{limitPlusOne}
